      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-ego-browser\",\n  \"version\": \"0.9.7\",\n  \"description\": \"ego-browser (ego-lite) integration plugin for DSH: structured browser-automation tools (34 ego_*) that drive the vendored ego runtime through ctx.subprocess, plus a realtime watch panel (live SSE screencast + direct mouse interaction + download capture + human-verification notice). Web shell: native right sidebar tab (dsh-better-sidebar fallback; no floating panel). TUI hosts (optional services): settings page, activity status bar, text-only side panel. Login import: Chrome extension bridge (modern Chrome/Edge) or non-destructive profile copy. Headless hosts: tools-only. [0.1.2-rc.1: verified compatible with DSH v0.1.2-rc.1 and v0.1.3-alpha.1]\",\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./dsh-plugin.json\": \"./dsh-plugin.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/\",\n    \"bin/\",\n    \"runtime/\",\n    \"extension/\",\n    \"cordis.patch.yml\",\n    \"dsh-plugin.json\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"!**/*.map\"\n  ],\n  \"dsh\": {\n    \"engines\": {\n      \"dsh\": \">=0.1.2-rc.1\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"typecheck\": \"tsc -p tsconfig.json && tsc -p tsconfig.client.json\",\n    \"test\": \"vitest run\",\n    \"build\": \"tsdown -c tsdown.config.ts\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.3\",\n    \"schemastery\": \"^3.18.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-client-locale\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-client-store\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \">=0.1.2-rc.1\",\n    \"react\": \"^18.2.0\",\n    \"schemastery\": \"^3.18.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-store\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    },\n    \"schemastery\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.20.1\",\n    \"@types/react\": \"~18.3.31\",\n    \"@types/ws\": \"^8.5.10\",\n    \"jsdom\": \"^26.0.0\",\n    \"tsdown\": \"^0.15.0\",\n    \"typescript\": \"^5.9.0\",\n    \"vitest\": \"^3.2.0\",\n    \"ws\": \"^8.18.0\"\n  },\n  \"engines\": {\n    \"node\": \">=22\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Fisfzy/dsh-ego-browser.git\"\n  }\n}\n"
    },
